$users=$pdo->query('SELECT id,name,username,email,role,city,created_at,last_seen FROM users ORDER BY created_at DESC')->fetchAll();
?>
<section class="admin-page-head"><div><span class="kicker">ADMIN / USERS</span><h1>User Management</h1><p>Manage donor, receiver and administrator accounts.</p></div><div class="admin-count"><?=count($users)?> users</div></section>
<div class="admin-table-card"><div class="table-wrap"><table><thead><tr><th>User</th><th>Email</th><th>City</th><th>Role</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?=e($u['name'])?></b><small>@<?=e($u['username']??'')?></small></td><td><?=e($u['email'])?></td><td><?=e($u['city']?:'—')?></td><td><span class="badge info"><?=e($u['role'])?></span></td><td><?=e(date('d M Y',strtotime($u['created_at'])))?></td><td><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$u['id']?>"><select name="role"><option value="donor" <?=$u['role']==='donor'?'selected':''?>>Donor</option><option value="receiver" <?=$u['role']==='receiver'?'selected':''?>>Receiver</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Admin</option></select><button class="mini-btn">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
